class vector3d
{
public:
  float x, y, z;
  vector3d () {}
  vector3d (const vector3d& v) : x(v.x), y(v.y), z(v.z) {}
  vector3d& operator += (const vector3d& v)
  {
    x += v.x;
    y += v.y;
    z += v.z;
    return *this;
  }
};

inline vector3d operator * (const vector3d& v, float f)
{
  vector3d result;
  result.x = v.x * f;
  result.y = v.y * f;
  result.z = v.z * f;
  return result;
}

class entity
{
public:
  vector3d get_rel_position () const;
  void set_rel_position (const vector3d& p);
};

class water_object
{
  char padding[0x2c];
protected:
  entity *my_entity;
  char water_data[0x29c];
public:
  bool update (float dt);
};

class static_object : public water_object
{
public:
  bool update (float dt);
private:
  bool dont_move;
};

void WAVE_GlobalCurrent (vector3d *current);

bool static_object::update (float dt)
{
  if (!dont_move)
  {
    vector3d current, position (my_entity->get_rel_position ());

    WAVE_GlobalCurrent (&current);
    position += current * dt;

    my_entity->set_rel_position (position);
  }

  return water_object::update (dt);
}
